144: function formatTime(s){let n=Math.floor(s);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
145: function start(){mode='playing';player.x=170;player.y=floor;player.vx=player.vy=0;player.hp=3;player.inv=0;player.fire=0;player.dash=0;player.dashCd=0;boss.x=735;boss.hp=100;boss.attack=0;boss.phase=0;boss.stun=0;projectiles=[];enemyShots=[];particles=[];score=0;elapsed=0;time=0;sound(530,.11,'triangle')}
