148: function shoot(){if(player.fire>0)return;player.fire=.19;projectiles.push({x:player.x+player.face*23,y:player.y-41,vx:player.face*550,life:1.4});sound(580,.045,'square',.012)}
149: function enemyFire(){const dx=player.x-boss.x,dir=Math.sign(dx)||-1;let speed=260+(100-boss.hp)*1.3;for(let i=-1;i<=1;i++)enemyShots.push({x:boss.x-8,y:boss.y-80,vx:dir*speed,vy:i*105+((player.y-boss.y)*.13),life:2.7,r:9,type:boss.phase===1?'ember':'orb'});sound(145,.15,'sawtooth',.018)}
150: function update(dt){time+=dt;if(mode!=='playing')return;elapsed+=dt;
151:  player.anim+=dt;player.fire=Math.max(0,player.fire-dt);player.inv=Math.max(0,player.inv-dt);player.dashCd=Math.max(0,player.dashCd-dt);
152:  let left=keys.ArrowLeft||keys.KeyA,right=keys.ArrowRight||keys.KeyD;
153:  if(player.dash>0){player.dash-=dt;player.vx=player.face*570}else{player.vx=(right-left)*230;if(player.vx)player.face=Math.sign(player.vx)}
154:  if((keys.Space||keys.ArrowUp||keys.KeyW)&&player.ground){player.vy=-465;player.ground=false;sound(250,.06,'triangle',.015)}
155:  if((keys.ShiftLeft||keys.ShiftRight||keys.KeyK)&&player.dashCd<=0){player.dash=.18;player.dashCd=.8;player.inv=Math.max(player.inv,.35);player.vy*=.2;sound(320,.08,'sawtooth',.018)}
156:  if(keys.KeyJ||keys.KeyX||keys.ControlLeft)shoot();
157:  player.x+=player.vx*dt;player.vy+=1150*dt;player.y+=player.vy*dt;
158:  if(player.y>=floor){player.y=floor;player.vy=0;player.ground=true}player.x=clamp(player.x,40,920);
159:  // boss phases: shoot volley, swoop, then repeat; faster when hurt
160:  boss.anim+=dt;boss.stun=Math.max(0,boss.stun-dt);boss.blink=Math.max(0,boss.blink-dt);
161:  const rage=boss.hp<48?1.35:1;boss.attack+=dt*rage;
162:  if(boss.attack>2.65){boss.attack=0;boss.phase=(boss.phase+1)%3;if(boss.phase===0||boss.phase===1)enemyFire();else{boss.x=clamp(player.x+ (player.x<boss.x?105:-105),540,875);shake=5;puff(boss.x,floor-10,'#dc9c53',14);sound(90,.2,'sawtooth',.025);if(Math.abs(player.x-boss.x)<102&&player.y>floor-90)hurt()}}
163:  // soft positioning, animated idle
164:  if(boss.phase!==2){boss.x+=Math.sin(time*1.1)*12*dt;boss.x=clamp(boss.x,600,845)}
165:  // player shots
